  const esc = t => String(t == null ? '' : t).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
  const rb = v => (v == null || !isFinite(v) ? '–' : Math.round(v).toLocaleString('id-ID'));
